<?php
require_once 'config/auth.php'; require_once 'config/db.php'; $id=(int)($_GET['id']??0); $st=$pdo->prepare("SELECT * FROM Learning_paths WHERE id=? AND status='published'");$st->execute([$id]);$path=$st->fetch();if(!$path){http_response_code(404);exit('Learning path not found.');}
$items=$pdo->prepare("SELECT lpi.id,lpi.item_type,lpi.item_id,lpi.sort_order,lm.title,lm.category FROM Learning_path_items lpi JOIN Learning_materials lm ON lpi.item_type='learning' AND lm.id=lpi.item_id WHERE lpi.path_id=? AND lm.status='published' UNION ALL SELECT lpi.id,lpi.item_type,lpi.item_id,lpi.sort_order,t.title,t.category FROM Learning_path_items lpi JOIN Tutorials t ON lpi.item_type='tutorial' AND t.id=lpi.item_id WHERE lpi.path_id=? AND t.status='published' ORDER BY sort_order");$items->execute([$id,$id]);$items=$items->fetchAll();$title=$path['title'];include 'partials/header.php'; ?>
<div class="dashboard-head"><div><span class="eyebrow">LEARNING PATH · <?=e(ucfirst($path['level']))?></span><h1><?=e($path['title'])?></h1><p><?=e($path['description'])?></p></div><a class="btn small secondary" href="learning_paths.php">← Paths</a></div><section class="card"><div class="path-progress"><span id="pathProgressBar"></span></div><p><b id="pathDone">0</b> / <?=count($items)?> activities completed.</p><p id="pathSyncStatus" class="muted" role="status" aria-live="polite">Loading saved progress…</p></section><section class="timeline"><?php foreach($items as $i=>$item): ?><article class="card path-item" data-item="<?=e($item['item_type'].'-'.$item['item_id'])?>"><div class="path-number"><?=($i+1)?></div><div><span class="badge"><?=e(ucfirst($item['item_type']))?></span><h2><?=e($item['title'])?></h2><p><?=e($item['category'])?></p><a class="btn small" href="<?= $item['item_type']==='learning' ? 'learning.php' : 'tutorials.php' ?>">Open Activity →</a> <button class="btn small secondary mark-path" type="button">✓ Mark Complete</button></div></article><?php endforeach; ?></section>
<script>
const BA_PATH_ID=<?=intval($id)?>;const BA_PATH_API=<?=json_encode(url('api/learning_path_progress.php?path_id='.(int)$id))?>;const BA_PATH_CSRF=document.querySelector('meta[name="csrf-token"]')?.content||'';const BA_PATH_KEY='bayangan_path_'+BA_PATH_ID+'_'+<?=json_encode(public_player_key())?>;const BA_PATH_LEGACY_KEY='bayangan_path_'+BA_PATH_ID;const BA_ALLOW_LEGACY_IMPORT=<?=!empty($_SESSION['public_profile_restored']) ? 'false' : 'true'?>;const BA_PATH_CARDS=[...document.querySelectorAll('.path-item')];
let baPathDone=[];const baPathNormalize=a=>[...new Set((Array.isArray(a)?a:[]).map(String).filter(v=>/^(learning|tutorial)-[1-9][0-9]*$/.test(v)))];
function baPathSaveLocal(){try{localStorage.setItem(BA_PATH_KEY,JSON.stringify(baPathDone))}catch(e){}}
function baPathRefresh(){BA_PATH_CARDS.forEach(c=>{const k=c.dataset.item;c.classList.toggle('completed',baPathDone.includes(k));const b=c.querySelector('.mark-path');b.textContent=baPathDone.includes(k)?'✓ Completed':'✓ Mark Complete';b.setAttribute('aria-pressed',baPathDone.includes(k)?'true':'false')});document.getElementById('pathDone').textContent=baPathDone.length;document.getElementById('pathProgressBar').style.width=(BA_PATH_CARDS.length?baPathDone.length/BA_PATH_CARDS.length*100:0)+'%'}
async function baPathPost(itemKey,action){const r=await fetch(BA_PATH_API,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':BA_PATH_CSRF},body:JSON.stringify({path_id:BA_PATH_ID,item_key:itemKey,action})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Could not sync progress');return baPathNormalize(d.completed||[])}
BA_PATH_CARDS.forEach(c=>c.querySelector('.mark-path').addEventListener('click',async()=>{const k=c.dataset.item;const was=baPathDone.includes(k);baPathDone=was?baPathDone.filter(x=>x!==k):[...baPathDone,k];baPathSaveLocal();baPathRefresh();try{baPathDone=await baPathPost(k,was?'uncomplete':'complete');baPathSaveLocal();baPathRefresh()}catch(e){const msg=document.getElementById('pathSyncStatus');if(msg)msg.textContent='Saved on this browser; server sync will retry when online.'}}));
(async()=>{let local=[];try{local=baPathNormalize(JSON.parse(localStorage.getItem(BA_PATH_KEY)||'[]'))}catch(e){}if(BA_ALLOW_LEGACY_IMPORT&&local.length===0){try{local=baPathNormalize(JSON.parse(localStorage.getItem(BA_PATH_LEGACY_KEY)||'[]'))}catch(e){}}try{const r=await fetch(BA_PATH_API,{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok||!d.ok)throw new Error();const remote=baPathNormalize(d.completed||[]);baPathDone=baPathNormalize([...remote,...local]);for(const k of baPathDone.filter(x=>!remote.includes(x)))await baPathPost(k,'complete');const msg=document.getElementById('pathSyncStatus');if(msg)msg.textContent='Progress synced to your active player profile.'}catch(e){baPathDone=local;const msg=document.getElementById('pathSyncStatus');if(msg)msg.textContent='Offline or not synced. Showing this browser’s saved progress.'}baPathSaveLocal();baPathRefresh()})();
</script>
<?php include 'partials/footer.php'; ?>